  expect(primaries(rendered.section())).toHaveLength(0);
  const box = await within(rendered.section()).findByRole('group', { name: 'Look up by name' });
  const offered = within(rendered.section()).getAllByRole('button', { name: 'Fill Disc and Track Numbers from titles' })[0];
